import type { ThemeId } from './art/themes';

// Tile legend:
//   #  ground      =  block (solid)       -  ledge (jump up through it)
//   ^  hazard      o  pickup              C  checkpoint
//   E  ground enemy (patrols)             B  bird (flies back and forth)
//   P  start       G  goal
//
// Reach, in tiles: Ricey jumps ~4 high and ~5 across; Ramen ~3 high and ~6
// across, ~9 with a dash. Walls of 5+ need Ricey's climb; gaps of 7 need
// Ramen's dash. Maps are generated by a layout script, but are fine to hand-edit.

export interface LevelDef {
  theme: ThemeId;
  name: string;
  country: string;
  /** Shown when the level is finished. */
  clear: string;
  zh: { name: string; country: string; clear: string };
  map: string[];
}

